 50  * { box-sizing: border-box; }
 51  html { -webkit-text-size-adjust: 100%; }
 52  body {
 53    margin: 0;
 54    background: var(--bg);
 55    color: var(--text);
 56    font-family: var(--font);
 57    font-size: 16px;
 58    line-height: 1.6;
 59    -webkit-font-smoothing: antialiased;
 60  }
 61  img { max-width: 100%; height: auto; }
 62  a { color: var(--primary-ink); }
 63  h1, h2, h3 { line-height: 1.2; }
 64  
 65  .container { max-width: 1160px; margin: 0 auto; padding: 0 24px; }
 66  .sr-only {
 67    position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
 68    overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
 69  }
 70  
 71  /* ---------- buttons ---------- */
 72  .btn {
 73    display: inline-flex; align-items: center; justify-content: center; gap: 8px;
 74    min-height: 44px; padding: 0 20px; border-radius: 12px; border: 1px solid transparent;
 75    font: inherit; font-size: 15px; font-weight: 600; line-height: 1.25; text-align: center;
 76    text-decoration: none; cursor: pointer;
 77  }
 78  .btn-sm { min-height: 36px; padding: 0 14px; font-size: 14px; border-radius: 10px; }
 79  .btn-lg { min-height: 50px; padding: 0 24px; font-size: 16px; }
 80  .btn-block { display: flex; width: 100%; }
 81  .btn-primary { background: var(--primary); color: var(--on-primary); }
 82  .btn-ghost { background: transparent; color: var(--text); border-color: var(--border); }
 83  .btn-danger { background: transparent; color: var(--danger); border-color: var(--danger-border); }
 84  
 85  /* ---------- promo ---------- */
 86  .promo {
 87    width: 600px; 
 88    margin: 0 auto;
 89    padding: 8px 16px;
 90    border-radius: 0 0 12px 12px;
 91    background: var(--promo-bg);
 92    color: var(--promo-text);
 93    font-size: 14px;
 94    text-align: center;
 95  }
 96  .promo p { margin: 0; }
 97  .promo a { color: var(--promo-link); font-weight: 600; }
 98  
 99  /* ---------- header ---------- */
100  .site-header { position: sticky; top: 0; z-index: 20; background: var(--bg); border-bottom: 1px solid var(--border); }
101  .header-inner { display: flex; align-items: center; gap: 24px; min-height: 64px; }
102  .brand {
103    display: inline-flex; align-items: center; gap: 10px; padding: 4px 0;
104    color: var(--text); font-size: 19px; font-weight: 800; letter-spacing: -0.01em; text-decoration: none;
105  }
106  .brand img { display: block; }
107  .main-nav { flex: 1; display: flex; justify-content: center; }
108  
109  .nav-links { display: flex; gap: 24px; max-width: 420px; overflow: hidden; white-space: nowrap; margin: 0; padding: 0; list-style: none; }
110  .nav-links a { display: inline-block; padding: 8px 0; color: var(--muted); font-size: 15px; font-weight: 500; text-decoration: none; white-space: nowrap; }
111  .header-actions { display: flex; align-items: center; gap: 12px; margin-left: auto; }
112  .nav-login { display: inline-block; padding: 8px 4px; color: var(--text); font-size: 15px; font-weight: 500; text-decoration: none; white-space: nowrap; }
113  #header-cta { flex-shrink: 0; white-space: nowrap; }
114  .menu-toggle {
115    display: none; width: 40px; height: 40px; align-items: center; justify-content: center; flex-shrink: 0;
116    border-radius: 10px; border: 1px solid var(--border); background: var(--surface); color: var(--text); cursor: pointer;
117  }
118  @media (max-width: 1023px) {
119    .main-nav, .nav-login { display: none; }
120    .menu-toggle { display: inline-flex; }
121  }
