128  .hero { padding: 48px 0 40px; text-align: center; }
129  .hero-inner { max-width: 820px; }
130  .hero-art { display: block; width: 100%; max-width: 720px; height: auto; margin: 0 auto 32px; border-radius: 16px; box-shadow: var(--shadow); }
